Here’s a Python implementation using `Decimal` for accurate currency calculations. Discount codes map to percentage discounts and are applied to the cart subtotal.

```python
from decimal import Decimal, ROUND_HALF_UP

DISCOUNTS = {
    "SAVE10": Decimal("10"),  # 10% off
    "SAVE20": Decimal("20"),  # 20% off
}

def calculate_total(products, discount_code=None):
    subtotal = Decimal("0")

    for product in products:
        price = Decimal(str(product["price"]))
        quantity = product["quantity"]

        if not price.is_finite() or price < 0:
            raise ValueError("Prices must be finite and non-negative")
        if isinstance(quantity, bool) or not isinstance(quantity, int) or quantity < 0:
            raise ValueError("Quantities must be non-negative integers")

        subtotal += price * quantity

    discount_percent = Decimal("0")
    if discount_code:
        code = discount_code.strip().upper()
        if code not in DISCOUNTS:
            raise ValueError("Invalid discount code")
        discount_percent = DISCOUNTS[code]

    total = subtotal * (Decimal("1") - discount_percent / Decimal("100"))
    return total.quantize(Decimal("0.01"), rounding=ROUND_HALF_UP)


cart = [
    {"price": "19.99", "quantity": 2},
    {"price": "5.50", "quantity": 1},
]

print(calculate_total(cart, "SAVE10"))  # 40.93
```

This calculates the total before taxes or shipping.

